    """Return True if s is a concatenation of words from `words` (each usable any number of times), else False."""
    ...

solution:
def word_break(s, words):
    dictionary = set(words)
    longest = max(map(len, dictionary), default=0)
    splittable = [True] + [False] * len(s)       # splittable[i]: the first i characters can be split into words
    for end in range(1, len(s) + 1):
        for start in range(max(0, end - longest), end):
            if splittable[start] and s[start:end] in dictionary:
                splittable[end] = True
                break
    return splittable[len(s)]
